const input = $json || {};
const config = input.config || {};
const family = config.family || {};
const childConfig = family.child || {};
const preferences = {
  ...(family.preferences || {}),
  ...(input.preferences || {})
};

const birthDate = input.child?.birthDate || childConfig.birthDate;
if (!birthDate) {
  throw new Error('Missing child birthDate. Provide config.family.child.birthDate or input.child.birthDate.');
}

function parseDateOnly(value) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) {
    throw new Error('child birthDate must use YYYY-MM-DD format.');
  }
  return new Date(Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3])));
}

function calculateAgeMonths(startDate, nowDate) {
  let months = (nowDate.getUTCFullYear() - startDate.getUTCFullYear()) * 12;
  months += nowDate.getUTCMonth() - startDate.getUTCMonth();
  if (nowDate.getUTCDate() < startDate.getUTCDate()) {
    months -= 1;
  }
  return Math.max(0, months);
}

function ageLabelFromMonths(months) {
  if (months < 12) {
    return `${months} mois`;
  }
  const years = Math.floor(months / 12);
  const remainingMonths = months % 12;
  if (remainingMonths === 0) {
    return years === 1 ? '1 an' : `${years} ans`;
  }
  return `${years} an${years > 1 ? 's' : ''} et ${remainingMonths} mois`;
}

const now = input.now ? new Date(input.now) : new Date();
if (Number.isNaN(now.getTime())) {
  throw new Error('Invalid now date-time.');
}

const birth = parseDateOnly(birthDate);
const ageMonths = calculateAgeMonths(birth, now);
const ageYears = Math.floor(ageMonths / 12);

return [
  {
    json: {
      child: {
        birthDate,
        ageMonths,
        ageYears,
        ageLabel: ageLabelFromMonths(ageMonths)
      },
      recentMeetings: input.recentMeetings || [],
      recentCategories: input.recentCategories || [],
      existingTopics: input.existingTopics || [],
      openDecisions: input.openDecisions || [],
      topicBacklog: input.topicBacklog || [],
      preferences
    }
  }
];
